1	// Pre-push OPF rewrite for entire/checkpoints/v1.
2	//
3	// This is the ONLY production code path that runs the OPF-augmented
4	// redaction entry points. Post-commit condensation stays on 7-layer
5	// for predictable latency; OPF runs here, once per push, after the
6	// user opted in via settings.
7	package strategy
8	
9	import (
10		"context"
11		"crypto/sha256"
12		"errors"
13		"fmt"
14		"io"
15		"log/slog"
16		"math"
17		"os"
18		"strconv"
19		"strings"
20	
21		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
22		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
23		"github.com/entireio/cli/cmd/entire/cli/logging"
24		"github.com/entireio/cli/cmd/entire/cli/paths"
25		"github.com/entireio/cli/cmd/entire/cli/trailers"
26		"github.com/entireio/cli/redact"
27		"github.com/go-git/go-git/v6"
28		"github.com/go-git/go-git/v6/plumbing"
29		"github.com/go-git/go-git/v6/plumbing/filemode"
30		"github.com/go-git/go-git/v6/plumbing/object"
31		"github.com/go-git/go-git/v6/storage"
32	)
33	
34	// V1DivergedError: local entire/checkpoints/v1 has commits that aren't
35	// ancestors of the remote tip (force-push or another machine pushed).
36	// Rewriting under divergence would silently rebase rejected work, so
37	// we refuse.
38	type V1DivergedError struct {
39		Local, Remote, MergeBase plumbing.Hash
40	}
41	
42	func (e *V1DivergedError) Error() string {
43		return fmt.Sprintf("entire/checkpoints/v1 has diverged from remote (local=%s remote=%s merge_base=%s); "+
44			"fetch the remote and either reset entire/checkpoints/v1 to <remote>/entire/checkpoints/v1 "+
45			"or run `entire doctor --recover-v1` before pushing",
46			e.Local.String()[:7], e.Remote.String()[:7], e.MergeBase.String()[:7])
47	}
48	
49	// BootstrapTooLargeError: first push to a remote with no v1 yet, but
50	// more unpushed commits than the safety cap. OPF inference is ~30s per
51	// commit, so unbounded bootstraps could take hours.
52	type BootstrapTooLargeError struct {
53		Count, Limit int
54	}
55	
56	func (e *BootstrapTooLargeError) Error() string {
57		return fmt.Sprintf("OPF bootstrap would rewrite %d entire/checkpoints/v1 commits "+
58			"(limit %d). Set ENTIRE_OPF_BOOTSTRAP_LIMIT=<N> or =unlimited to override, "+
59			"or push without OPF (ENTIRE_OPF=no git push) to bring the remote into sync first",
60			e.Count, e.Limit)
61	}
62	
63	// V1RefMovedError: another worktree advanced the local ref during our
64	// rewrite (CAS conflict). Orphan rewritten objects sit in .git/objects
65	// until git gc --prune; no manual cleanup needed.
66	type V1RefMovedError struct {
67		Expected, Actual plumbing.Hash
68	}
69	
70	func (e *V1RefMovedError) Error() string {
71		return fmt.Sprintf("entire/checkpoints/v1 moved during OPF rewrite "+
72			"(expected %s, found %s); another local worktree advanced the ref "+
73			"mid-rewrite — re-run `git push` (no fetch needed; the move was local)",
74			e.Expected.String()[:7], e.Actual.String()[:7])
75	}
76	
77	// OPFRuntimeFailedError: the OPF circuit breaker tripped mid-rewrite.
78	// Some blobs were silently downgraded to 7-layer; tagging those commits
79	// as Entire-OPF-Applied would be a privacy regression (future pushes
80	// would skip them while their content is 7-layer-only). Abort before
81	// CAS so the user fixes their OPF install and retries.
82	type OPFRuntimeFailedError struct {
83		OPFCommand string
84	}
85	
86	func (e *OPFRuntimeFailedError) Error() string {
87		return fmt.Sprintf("OPF runtime failed during pre-push rewrite (command=%q); "+
88			"aborting push so 7-layer content isn't tagged as 8-layer-applied. "+
89			"Run `%s --help` to verify your OPF install, then retry. Or set "+
90			"ENTIRE_OPF=no on the push to skip OPF for this push only.",
91			e.OPFCommand, e.OPFCommand)
92	}
93	
94	const (
95		// bootstrapDefaultLimit caps first-push history rewrites. Picked
96		// to bound worst-case wall-clock at ~50min @ 30s/commit.
97		bootstrapDefaultLimit = 100
98		bootstrapEnvVar       = "ENTIRE_OPF_BOOTSTRAP_LIMIT"
99	)
100	
101	func resolveBootstrapLimit() int {
102		v := strings.TrimSpace(os.Getenv(bootstrapEnvVar))
103		switch {
104		case v == "":
105			return bootstrapDefaultLimit
106		case strings.EqualFold(v, "unlimited"):
107			return math.MaxInt32
108		}
109		if n, err := strconv.Atoi(v); err == nil && n > 0 {
110			return n
111		}
112		return bootstrapDefaultLimit
113	}
114	
115	// RewriteUnpushedV1WithOPF re-redacts unpushed entire/checkpoints/v1
116	// commits with OPF, builds new commits carrying Entire-OPF-Applied:
117	// true, and CAS-updates the local ref. Idempotent: already-applied
118	// commits are re-parented without re-running OPF.
119	//
120	// Caller checks redact.OPFEnabled() and skips this when OPF is off.
121	// Returns one of {V1DivergedError, BootstrapTooLargeError,
122	// V1RefMovedError, OPFRuntimeFailedError} for privacy-critical
123	// failures — the pre-push hook propagates these so git push aborts.
124	func RewriteUnpushedV1WithOPF(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
125		localTip, err := readV1Tip(repo, plumbing.NewBranchReferenceName(paths.MetadataBranchName))
126		if err != nil {
127			return plumbing.ZeroHash, fmt.Errorf("read local v1: %w", err)
128		}
129		if localTip.IsZero() {
130			return plumbing.ZeroHash, nil // no checkpoints yet
131		}
132		remoteTip, err := resolveRemoteV1Tip(ctx, repo, target)
133		if err != nil {
134			return plumbing.ZeroHash, fmt.Errorf("read remote v1: %w", err)
135		}
136	
137		if !remoteTip.IsZero() {
138			mergeBase, mbErr := computeMergeBase(repo, localTip, remoteTip)
139			if mbErr != nil {
140				return plumbing.ZeroHash, fmt.Errorf("compute merge-base: %w", mbErr)
141			}
142			if mergeBase != remoteTip {
143				return plumbing.ZeroHash, &V1DivergedError{Local: localTip, Remote: remoteTip, MergeBase: mergeBase}
144			}
145		}
146	
147		unpushed, err := listUnpushedV1Commits(repo, localTip, remoteTip)
148		if err != nil {
149			return plumbing.ZeroHash, fmt.Errorf("list unpushed v1 commits: %w", err)
150		}
151		if len(unpushed) == 0 {
152			return localTip, nil
153		}
154		if remoteTip.IsZero() {
155			if limit := resolveBootstrapLimit(); len(unpushed) > limit {
156				return plumbing.ZeroHash, &BootstrapTooLargeError{Count: len(unpushed), Limit: limit}
157			}
158		}
159	
160		parent := remoteTip
161		for _, c := range unpushed {
162			newHash, err := rebuildV1Commit(ctx, repo, c, parent)
163			if err != nil {
164				return plumbing.ZeroHash, fmt.Errorf("rebuild commit %s: %w", c.Hash.String()[:7], err)
165			}
166			parent = newHash
167		}
168	
169		// Fail-closed: if OPF tripped its breaker mid-rewrite, some blobs
170		// got 7-layer fallback. Don't CAS — the orphan commits get GC'd.
171		if redact.OPFBreakerTripped() {
172			return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
173		}
174		if err := atomicSetV1Ref(repo, localTip, parent); err != nil {
175			return plumbing.ZeroHash, err
176		}
177		return parent, nil
178	}
179	
180	func readV1Tip(repo *git.Repository, refName plumbing.ReferenceName) (plumbing.Hash, error) {
181		ref, err := repo.Reference(refName, true)
182		if err != nil {
183			if errors.Is(err, plumbing.ErrReferenceNotFound) {
184				return plumbing.ZeroHash, nil
185			}
186			return plumbing.ZeroHash, fmt.Errorf("resolve ref %s: %w", refName, err)
187		}
188		return ref.Hash(), nil
189	}
190	
191	// opfRewriteFetchTmpRef is the temp ref used to stage the URL-fetched
192	// remote v1 tip during OPF rewrite. Cleaned up at the end of each
193	// resolveRemoteV1Tip call so the tracking is invisible to the user.
194	const opfRewriteFetchTmpRef = FetchTmpRefPrefix + "opf-rewrite-v1"
195	
196	// resolveRemoteV1Tip returns the hash of the remote's
197	// entire/checkpoints/v1 tip.
198	//
199	// When target is a remote name (e.g., "origin"), looks up the local
200	// tracking ref `refs/remotes/<target>/entire/checkpoints/v1`. When
201	// target is a URL (checkpoint_remote configured), fetches the v1 ref
202	// from the URL into a temporary local ref so the rewrite can see what's
203	// already on the remote — otherwise every push would re-redact the
204	// entire history as a "bootstrap" since URL-based remotes have no
205	// tracking refs locally.
206	//
207	// Returns ZeroHash with no error when the remote has no v1 yet (genuine
208	// bootstrap case). Fetch failures fall back to ZeroHash + a warning
209	// log; the rewrite then treats the push as bootstrap rather than
210	// blocking the user on a transient network issue.
211	func resolveRemoteV1Tip(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
212		if !remote.IsURL(target) {
213			return readV1Tip(repo, plumbing.NewRemoteReferenceName(target, paths.MetadataBranchName))
214		}
215		srcRef := "refs/heads/" + paths.MetadataBranchName
216		if err := fetchURLIntoTmpRef(ctx, target, srcRef, opfRewriteFetchTmpRef, "v1 for OPF rewrite", true); err != nil {
217			logging.Warn(ctx, "OPF rewrite: failed to fetch remote v1 from URL; treating push as bootstrap",
218				slog.String("error", err.Error()),
219			)
220			return plumbing.ZeroHash, nil
221		}
222		defer func() {
223			if err := repo.Storer.RemoveReference(plumbing.ReferenceName(opfRewriteFetchTmpRef)); err != nil {
224				logging.Debug(ctx, "OPF rewrite: failed to clean up temp ref",
225					slog.String("error", err.Error()),
226				)
227			}
228		}()
229		ref, err := repo.Reference(plumbing.ReferenceName(opfRewriteFetchTmpRef), true)
230		if err != nil {
231			if errors.Is(err, plumbing.ErrReferenceNotFound) {
232				return plumbing.ZeroHash, nil
233			}
234			return plumbing.ZeroHash, fmt.Errorf("resolve fetched v1 ref: %w", err)
235		}
236		return ref.Hash(), nil
237	}
238	
239	// computeMergeBase returns the merge-base commit hash. Multi-base
240	// (criss-cross) and unrelated-histories both return ZeroHash —
241	// caller treats those as diverged.
242	func computeMergeBase(repo *git.Repository, local, remote plumbing.Hash) (plumbing.Hash, error) {
243		lc, err := repo.CommitObject(local)
244		if err != nil {
245			return plumbing.ZeroHash, fmt.Errorf("load local commit: %w", err)
246		}
247		rc, err := repo.CommitObject(remote)
248		if err != nil {
249			return plumbing.ZeroHash, fmt.Errorf("load remote commit: %w", err)
250		}
251		bases, err := lc.MergeBase(rc)
252		if err != nil {
253			return plumbing.ZeroHash, fmt.Errorf("merge-base: %w", err)
254		}
255		if len(bases) != 1 {
256			return plumbing.ZeroHash, nil
257		}
258		return bases[0].Hash, nil
259	}
260	
261	// listUnpushedV1Commits returns commits reachable from localTip but not
262	// remoteTip, in graph order (oldest-first). Graph order matters more
263	// than timestamp order — commits made in rapid succession can share
264	// Author.When; the parent chain is the unambiguous truth.
265	//
266	// Optimization: the caller (RewriteUnpushedV1WithOPF) has already
267	// validated that remoteTip is the unique merge-base of local and
268	// remote, which means v1 is linear and remoteTip is an ancestor of
269	// localTip. So walking back from localTip, the FIRST commit we hit
270	// whose hash equals remoteTip is the boundary — no need to pre-build
271	// a full remote-reachability set. This drops the cost from
272	// O(local + remote history) to O(unpushed) per call.
273	func listUnpushedV1Commits(repo *git.Repository, localTip, remoteTip plumbing.Hash) ([]*object.Commit, error) {
274		iter, err := repo.Log(&git.LogOptions{From: localTip})
275		if err != nil {
276			return nil, fmt.Errorf("log local tip: %w", err)
277		}
278		defer iter.Close()
279	
280		var unpushed []*object.Commit
281		if walkErr := iter.ForEach(func(c *object.Commit) error {
282			if !remoteTip.IsZero() && c.Hash == remoteTip {
283				return errStop
284			}
285			unpushed = append(unpushed, c)
286			return nil
287		}); walkErr != nil && !errors.Is(walkErr, errStop) {
288			return nil, fmt.Errorf("walk local v1 history: %w", walkErr)
289		}
290		// reverse for oldest-first
291		for i, j := 0, len(unpushed)-1; i < j; i, j = i+1, j-1 {
292			unpushed[i], unpushed[j] = unpushed[j], unpushed[i]
293		}
294		return unpushed, nil
295	}
296	
297	// rebuildV1Commit re-parents the commit onto parent. Already-applied
298	// commits keep their tree (idempotent); unapplied commits get an
299	// OPF-redacted tree + Entire-OPF-Applied: true trailer.
300	//
301	// Performance: we only redact files inside THIS commit's shard
302	// (sharded layout: <id[:2]>/<id[2:]>/*). Files outside that shard live
303	// at the same tree because git trees accumulate parent content — they
304	// belong to other commits and either are already redacted (prior
305	// OPF-applied push) or never will be (this user opted out then in).
306	// Walking them every push is O(N×commits) work for no privacy gain.
307	func rebuildV1Commit(ctx context.Context, repo *git.Repository, oldCommit *object.Commit, parent plumbing.Hash) (plumbing.Hash, error) {
308		newTree := oldCommit.TreeHash
309		if !trailers.HasOPFApplied(oldCommit.Message) {
310			tree, err := repo.TreeObject(oldCommit.TreeHash)
311			if err != nil {
312				return plumbing.ZeroHash, fmt.Errorf("load tree: %w", err)
313			}
314			// Parse the shard path from the commit subject. Falls back to
315			// "" (walk everything) for bootstrap commits and unrecognized
316			// subjects — the conservative default still produces correct
317			// output, just slower.
318			shardPath := parseShardPathFromCommitMessage(oldCommit.Message)
319			newTree, err = rebuildTreeWithOPF(ctx, repo, tree, "", shardPath)
320			if err != nil {
321				return plumbing.ZeroHash, err
322			}
323		}
324	
325		parents := []plumbing.Hash{}
326		if !parent.IsZero() {
327			parents = append(parents, parent)
328		}
329		c := &object.Commit{
330			Author:       oldCommit.Author,
331			Committer:    oldCommit.Committer,
332			Message:      trailers.AppendOPFAppliedTrailer(oldCommit.Message),
333			TreeHash:     newTree,
334			ParentHashes: parents,
335		}
336		// Sign the rewritten commit when commit signing is enabled, matching
337		// every other commit-construction site in this package (common.go,
338		// metadata_reconcile.go, push_common.go). Without this, a user who
339		// has signed checkpoint commits would see the rewrite produce
340		// unsigned commits — silently degrading their integrity story.
341		checkpoint.SignCommitBestEffort(ctx, c)
342		obj := repo.Storer.NewEncodedObject()
343		if err := c.Encode(obj); err != nil {
344			return plumbing.ZeroHash, fmt.Errorf("encode commit: %w", err)
345		}
346		hash, err := repo.Storer.SetEncodedObject(obj)
347		if err != nil {
348			return plumbing.ZeroHash, fmt.Errorf("store commit: %w", err)
349		}
350		return hash, nil
351	}
352	
353	// parseShardPathFromCommitMessage extracts the sharded path
354	// "<id[:2]>/<id[2:]>" from a "Checkpoint: <id>" subject line.
355	// Returns "" when the subject doesn't match (bootstrap commits, or
356	// historical commits with a different format) — callers walk the
357	// whole tree in that case.
358	func parseShardPathFromCommitMessage(message string) string {
359		firstLine, _, _ := strings.Cut(message, "\n")
360		const prefix = "Checkpoint: "
361		if !strings.HasPrefix(firstLine, prefix) {
362			return ""
363		}
364		id := strings.TrimSpace(firstLine[len(prefix):])
365		if len(id) != 12 {
366			return ""
367		}
368		for _, c := range id {
369			if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
370				return ""
371			}
372		}
373		return id[:2] + "/" + id[2:]
374	}
375	
376	// rebuildTreeWithOPF walks a tree and produces a new tree with
377	// OPF-redacted file blobs. content_hash.txt files are recomputed in a
378	// second pass against the new full.jsonl in the same directory.
379	//
380	// shardPath scopes the walk: only files at paths starting with
381	// shardPath get redacted; other shards (and the root-level entries
382	// outside the shard) are copied verbatim. Empty shardPath means walk
383	// everything (used for bootstrap/unknown-subject commits).
384	//
385	// Path-specific behavior (when in the target shard):
386	//   - content_hash.txt → SHA256 of the sibling full.jsonl's new bytes
387	//     (deferred; not redacted itself)
388	//   - everything else → redacted via checkpoint.RedactBlobBytes (OPF on).
389	//     The fail-closed policy intentionally redacts ANY regular file
390	//     inside the shard, not just a closed allowlist of suffixes — a
391	//     future blob type (e.g. .md prose, agent dumps, no-extension
392	//     transcript blobs) is redacted by default rather than slipping
393	//     through. RedactBlobBytes itself dispatches: .jsonl/.json get
394	//     JSON-aware leaf redaction (so free-form fields like Summary.Intent
395	//     / ReviewPrompt are scrubbed); other files get byte redaction. The
396	//     has-space gate inside OPF naturally excludes binary blobs from
397	//     paying the model cost.
398	func rebuildTreeWithOPF(ctx context.Context, repo *git.Repository, tree *object.Tree, pathPrefix, shardPath string) (plumbing.Hash, error) {
399		entries := make([]object.TreeEntry, 0, len(tree.Entries))
400		// deferredHashes records indexes of content_hash.txt entries we
401		// need to recompute after the full.jsonl in the same dir is built.
402		type deferred struct {
403			idx       int
404			entryName string
405			entryMode filemode.FileMode
406		}
407		var deferredHashes []deferred
408		var newFullJSONLHash plumbing.Hash
409	
410		for _, e := range tree.Entries {
411			switch e.Mode { //nolint:exhaustive // non-tree/blob modes fall through to copy
412			case filemode.Dir:
413				subPath := e.Name
414				if pathPrefix != "" {
415					subPath = pathPrefix + "/" + e.Name
416				}
417				// Shard-scoping: only descend into directories that lead
418				// to the target shard, the shard itself, or its
419				// descendants. Other shard subtrees stay byte-identical.
420				if !shouldDescend(subPath, shardPath) {
421					entries = append(entries, e)
422					continue
423				}
424				subTree, err := repo.TreeObject(e.Hash)
425				if err != nil {
426					return plumbing.ZeroHash, fmt.Errorf("load subtree %s/%s: %w", pathPrefix, e.Name, err)
427				}
428				newSub, err := rebuildTreeWithOPF(ctx, repo, subTree, subPath, shardPath)
429				if err != nil {
430					return plumbing.ZeroHash, err
431				}
432				entries = append(entries, object.TreeEntry{Name: e.Name, Mode: e.Mode, Hash: newSub})
433	
434			case filemode.Regular, filemode.Executable:
435				// Outside the target shard: copy verbatim. Inside (or when
436				// shardPath is empty for the bootstrap fallback): redact
437				// per file type.
438				if !insideShard(pathPrefix, shardPath) {
439					entries = append(entries, e)
440					continue
441				}
442				switch e.Name {
443				case paths.ContentHashFileName:
444					deferredHashes = append(deferredHashes, deferred{idx: len(entries), entryName: e.Name, entryMode: e.Mode})
445					entries = append(entries, e) // placeholder; fixed in second pass
446				default:
447					content, err := readBlob(repo, e.Hash)
448					if err != nil {
449						return plumbing.ZeroHash, fmt.Errorf("read blob %s/%s: %w", pathPrefix, e.Name, err)
450					}
451					newBytes := checkpoint.RedactBlobBytes(ctx, content, e.Name, true)
452					newHash, err := checkpoint.CreateBlobFromContent(repo, newBytes)
453					if err != nil {
454						return plumbing.ZeroHash, fmt.Errorf("write redacted blob %s/%s: %w", pathPrefix, e.Name, err)
455					}
456					entries = append(entries, object.TreeEntry{Name: e.Name, Mode: e.Mode, Hash: newHash})
457					if e.Name == paths.TranscriptFileName {
458						newFullJSONLHash = newHash
459					}
460				}
461			default:
462				entries = append(entries, e)
463			}
464		}
465	
466		for _, d := range deferredHashes {
467			if newFullJSONLHash.IsZero() {
468				continue // no transcript in this dir; keep original hash
469			}
470			jsonlBytes, err := readBlob(repo, newFullJSONLHash)
471			if err != nil {
472				return plumbing.ZeroHash, fmt.Errorf("read new transcript for content_hash: %w", err)
473			}
474			sum := sha256.Sum256(jsonlBytes)
475			hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(fmt.Sprintf("sha256:%x", sum)))
476			if err != nil {
477				return plumbing.ZeroHash, fmt.Errorf("write content_hash: %w", err)
478			}
479			entries[d.idx] = object.TreeEntry{Name: d.entryName, Mode: d.entryMode, Hash: hashBlob}
480		}
481	
482		newTree := &object.Tree{Entries: entries}
483		obj := repo.Storer.NewEncodedObject()
484		if err := newTree.Encode(obj); err != nil {
485			return plumbing.ZeroHash, fmt.Errorf("encode tree: %w", err)
486		}
487		hash, err := repo.Storer.SetEncodedObject(obj)
488		if err != nil {
489			return plumbing.ZeroHash, fmt.Errorf("store tree: %w", err)
490		}
491		return hash, nil
492	}
493	
494	// shouldDescend reports whether the walker should recurse into a
495	// directory at path. With an empty shardPath we descend everywhere
496	// (bootstrap fallback). Otherwise we descend only into the target
497	// shard, its ancestors (so we can reach it), and its descendants.
498	func shouldDescend(path, shardPath string) bool {
499		if shardPath == "" || path == "" {
500			// shardPath="" means "no scoping" (bootstrap fallback);
501			// path=="" is the root, which is the ancestor of every shard.
502			return true
503		}
504		if path == shardPath {
505			return true
506		}
507		// ancestor of shardPath: shardPath starts with path + "/"
508		if strings.HasPrefix(shardPath+"/", path+"/") {
509			return true
510		}
511		// descendant of shardPath: path starts with shardPath + "/"
512		return strings.HasPrefix(path+"/", shardPath+"/")
513	}
514	
515	// insideShard reports whether file blobs at pathPrefix should be
516	// redacted. Empty shardPath means "redact everywhere"; otherwise the
517	// path must equal shardPath or be a descendant of it.
518	func insideShard(pathPrefix, shardPath string) bool {
519		if shardPath == "" {
520			return true
521		}
522		if pathPrefix == shardPath {
523			return true
524		}
525		return strings.HasPrefix(pathPrefix+"/", shardPath+"/")
526	}
527	
528	func readBlob(repo *git.Repository, hash plumbing.Hash) ([]byte, error) {
529		blob, err := repo.BlobObject(hash)
530		if err != nil {
531			return nil, fmt.Errorf("blob: %w", err)
532		}
533		r, err := blob.Reader()
534		if err != nil {
535			return nil, fmt.Errorf("blob reader: %w", err)
536		}
537		defer func() { _ = r.Close() }()
538		data, err := io.ReadAll(r)
539		if err != nil {
540			return nil, fmt.Errorf("blob read: %w", err)
541		}
542		return data, nil
543	}
544	
545	// atomicSetV1Ref CAS-updates the local v1 ref. A concrete
546	// ErrReferenceHasChanged from the storer means another worktree
547	// advanced the ref during our rewrite — return V1RefMovedError so the
548	// hook aborts the push. Other errors (I/O, packed-ref locks, storage
549	// bugs) get wrapped as-is so they aren't misreported as concurrency
550	// failures.
551	func atomicSetV1Ref(repo *git.Repository, expectedOld, newHash plumbing.Hash) error {
552		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
553		err := repo.Storer.CheckAndSetReference(
554			plumbing.NewHashReference(refName, newHash),
555			plumbing.NewHashReference(refName, expectedOld),
556		)
557		if err == nil {
558			return nil
559		}
560		if errors.Is(err, storage.ErrReferenceHasChanged) {
561			actual := plumbing.ZeroHash
562			if cur, refErr := repo.Reference(refName, true); refErr == nil {
563				actual = cur.Hash()
564			}
565			return &V1RefMovedError{Expected: expectedOld, Actual: actual}
566		}
567		return fmt.Errorf("set v1 ref: %w", err)
568	}
