527	// parseShardPathFromCommitMessage extracts the sharded path
528	// "<id[:2]>/<id[2:]>" from a "Checkpoint: <id>" subject line.
529	// Returns "" when the subject doesn't match (bootstrap commits, or
530	// historical commits with a different format) — callers walk the
531	// whole tree in that case.
532	func parseShardPathFromCommitMessage(message string) string {
533		firstLine, _, _ := strings.Cut(message, "\n")
534		const prefix = "Checkpoint: "
535		if !strings.HasPrefix(firstLine, prefix) {
536			return ""
537		}
538		id := strings.TrimSpace(firstLine[len(prefix):])
539		if len(id) != 12 {
540			return ""
541		}
542		for _, c := range id {
543			if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
544				return ""
545			}
546		}
547		return id[:2] + "/" + id[2:]
548	}
549	
550	// isRedactableBlobName reports whether a file at the given name should
551	// flow through OPF. The policy is fail-closed: every regular file
552	// inside the shard is redacted EXCEPT content_hash.txt, which is
553	// recomputed against the new full.jsonl in a deferred pass.
554	//
555	// Why an open policy: a closed allowlist (.jsonl/.txt/.json only)
556	// would silently skip any future blob type that lands in a shard
557	// — .md prose, agent dumps, no-extension transcript blobs — and ship
558	// it verbatim with the Entire-OPF-Applied trailer attached. Inverting
559	// to "redact everything except the deferred file" means new types are
560	// covered by default; opting out requires an explicit code change.
561	//
562	// RedactBlobBytes itself handles arbitrary content: .jsonl/.json go
563	// through JSON-aware leaf redaction; anything else gets byte
564	// redaction over the raw content. The OPF has-space gate excludes
565	// binary blobs from paying inference cost.
566	func isRedactableBlobName(name string) bool {
567		return name != paths.ContentHashFileName
568	}
569	
570	// collectTreeBlobs walks tree and appends every redactable blob's
571	// content + full tree path to the parallel output slices. The same
572	// shard-scoping rules as rebuildTreeWithCachedRedaction apply.
573	//
574	// blobs[i] and paths[i] correspond: paths[i] is the full path within
